@sig trait RequestQualification_Api {
  def id: Art.BridgeId
  def request_boundary_facts_Id : Art.PortId
  def request_facts_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var request_facts: Factory_Dispatch_Coordinator.RequestFacts = $

  def put_request_facts(value : Factory_Dispatch_Coordinator.RequestFacts) : Unit = {
    Contract(
      Modifies(request_facts),
      Ensures(
        request_facts == value
      )
    )
    Spec {
      request_facts = value
    }

    Art.putValue(request_facts_Id, Factory_Dispatch_Coordinator.RequestFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class RequestQualification_Initialization_Api (
  val id: Art.BridgeId,
  val request_boundary_facts_Id : Art.PortId,
  val request_facts_Id : Art.PortId) extends RequestQualification_Api

@datatype class RequestQualification_Operational_Api (
  val id: Art.BridgeId,
  val request_boundary_facts_Id : Art.PortId,
  val request_facts_Id : Art.PortId) extends RequestQualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var request_boundary_facts: Factory_Dispatch_Coordinator.RequestBoundaryFacts = $

  def get_request_boundary_facts() : Option[Factory_Dispatch_Coordinator.RequestBoundaryFacts] = {
    Contract(
      Ensures(
        Res == Some(request_boundary_facts)
      )
    )
    val value : Option[Factory_Dispatch_Coordinator.RequestBoundaryFacts] = Art.getValue(request_boundary_facts_Id) match {
      case Some(Factory_Dispatch_Coordinator.RequestBoundaryFacts_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port request_boundary_facts.  Expecting 'Factory_Dispatch_Coordinator.RequestBoundaryFacts_Payload' but received ${v}")
        None[Factory_Dispatch_Coordinator.RequestBoundaryFacts]()
      case _ => None[Factory_Dispatch_Coordinator.RequestBoundaryFacts]()
    }
    return value
  }
}
